import {useState, type Dispatch, type SetStateAction} from 'react'
import {SharedChecklistComponent} from '@github-ui/shared-checklist-component'
import type {StepData} from '@github-ui/shared-checklist-component/Stepper'
import {updateSetting} from '../../helpers/settings-helper'
import {DashboardDismissalSettings} from '../../constants/dashboard-settings'
import {ChecklistComplete} from './ChecklistComplete/ChecklistComplete'
import {useClickAnalytics} from '@github-ui/use-analytics'
import type {Dismissals} from '../../types/dismissals-types'
import type {ChecklistActions, GettingStartedChecklist} from '../../types/checklist-types'
import {getChecklistData} from './NewUserGettingStartedChecklistData'

interface NewUserGettingStartedChecklistProps {
  checklist: GettingStartedChecklist
  checklistActions: ChecklistActions
  dismissed: boolean
  setDismissedModules: Dispatch<SetStateAction<Dismissals>>
}

export const NewUserGettingStartedChecklist = ({
  checklist,
  checklistActions,
  dismissed,
  setDismissedModules,
}: NewUserGettingStartedChecklistProps) => {
  const gettingStartedSteps: StepData[] = getChecklistData(checklistActions)

  const [isDismissed, setIsDismissed] = useState<boolean>(dismissed)

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const handleDismiss = () => {
    setIsDismissed(true)
    setDismissedModules(prev => ({
      ...prev,
      getting_started_dismissed: true,
    }))
    updateSetting(DashboardDismissalSettings.GettingStarted, true)

    sendClickAnalyticsEvent({
      category: 'zero_user_dashboard',
      action: 'click.getting_started.dismiss',
    })
  }

  const isComplete = Object.values(checklist).every(Boolean)

  return isDismissed ? null : (
    <section aria-labelledby="checklist-heading" data-testid="getting-started-checklist-section">
      {isComplete ? (
        <ChecklistComplete onDismiss={handleDismiss} />
      ) : (
        <SharedChecklistComponent
          stepMetadata={gettingStartedSteps}
          dismissed={false}
          checklist={[checklist.has_created_repo, checklist.has_tried_copilot, checklist.has_customized_account]}
          /* We do not need this functionality, but it is here due to multiple implementation of this component */
          onChecklistChange={() => {}}
          onDismiss={handleDismiss}
          dismissText="Remove from dashboard"
          dashboardChecklist
        />
      )}
    </section>
  )
}

export default NewUserGettingStartedChecklist

try{ NewUserGettingStartedChecklist.displayName ||= 'NewUserGettingStartedChecklist' } catch {}