import {Heading, Link} from '@primer/react'
import {useClickAnalytics} from '@github-ui/use-analytics'
import styles from './ResourceCard.module.css'

interface Analytics {
  category: string
  action: string
}

export interface ResourceCardProps {
  /**
   * Optional URL to link to when the card is clicked. If not provided, the card will not be clickable.
   */
  href?: string
  /**
   * Icon to display at the top of the card. This can be any valid React node, but should typically be an octicon.
   * Should ideally have a size of 16x16 pixels `size={'small'}`.
   */
  icon: string | React.ReactNode
  /**
   * Title text to display on the card.
   */
  title: string
  /**
   * Optional description text to display below the title on the card.
   */
  description?: string
  /**
   * Optional analytics data to send when the card is clicked. If not provided, no analytics event will be sent.
   */
  analytics?: Analytics
}

export const ResourceCard = ({href, icon, title, description, analytics}: ResourceCardProps) => {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  // Turns title into a lowercase string with underscores and removes non-word characters
  const sanitizedTitle = title
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^\w_]/g, '')

  return (
    <Link
      href={href}
      className={styles.link}
      target="_blank"
      rel="noopener noreferrer"
      onClick={() => {
        if (!analytics) return

        sendClickAnalyticsEvent({
          category: analytics.category,
          action: analytics.action,
        })
      }}
      data-testid={`resource-card-${sanitizedTitle}`}
    >
      <div className={styles.cardShadow}>
        <div className={styles.card}>
          <div className={styles.cardIcon}>{icon}</div>
          <div className={styles.cardContent}>
            <Heading as="h3" className={styles.heading}>
              {title}
            </Heading>
            {description ? <div className={styles.description}>{description}</div> : null}
          </div>
        </div>
      </div>
    </Link>
  )
}

try{ ResourceCard.displayName ||= 'ResourceCard' } catch {}